def minWorkSessions(tasks, sessionTime):
    n = len(tasks)
    size = 1 << n
    sess = [n + 1] * size
    load = [0] * size
    sess[0] = 1
    for mask in range(size):
        s = sess[mask]
        if s > n:
            continue
        l = load[mask]
        for i in range(n):
            bit = 1 << i
            if mask & bit:
                continue
            t = tasks[i]
            if l + t <= sessionTime:
                ns, nl = s, l + t
            else:
                ns, nl = s + 1, t
            nm = mask | bit
            if ns < sess[nm] or (ns == sess[nm] and nl < load[nm]):
                sess[nm] = ns
                load[nm] = nl
    return sess[size - 1]
